# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={385:'На обличчі пані Ставської промайнула тінь смутку й утоми.',386:'— І нічого, жодної звістки? — спитав управитель.',387:'Молода пані повільно похитала головою; не певен, чи зітхнула, але дуже тихо...',388:'— Отака доля молодої й гарненької жінки! — вигукнула старша пані. — Ні дівчина, ні заміжня...',389:'— Матусю!...',390:'— Ні вдова, ні розлучена, одним словом — невідомо хто й невідомо чому... Геленко, кажи собі що хочеш, а я тобі кажу: Людвік уже помер...',391:'— Матусю!... Матусю!...',392:'— Так, — запально провадила мати. — Ми всі тут чекаємо на нього щодня, щогодини, але марно... Або він помер, або зрікся тебе, тож ти не зобов’язана чекати...',393:'В обох пань на очах виступили сльози: у матері від гніву, а в доньки... Хто знає?... Може, від жалю за зламаним життям.',394:'Раптом мені спала на думку ідея, яку (якби йшлося не про мене) я назвав би геніальною. Та байдуже, як її назвати.',395:'Досить сказати, що в моєму обличчі й усій постаті було щось таке, що, коли я вмостився на стільці, закинув ногу на ногу й відкашлявся, усі втупили в мене погляди — навіть маленька Геленка.',396:'— Наше знайомство, — сказав я, — надто коротке, щоб я наважився...',397:'— Байдуже! — перебив мене пан Вірський. — Добрі послуги приймають і від незнайомців.',398:'— Наше знайомство, — провадив я, кинувши на нього докірливий погляд, — справді недовге. Проте дозвольте, щоб не тільки я, а й пан Вокульський скористався своїми зв’язками, аби розшукати вашого чоловіка...',399:'— А-а!... — застогнала старша пані так, що це не можна було вважати виявом радості.',400:'— Матусю! — втрутилася пані Ставська.',401:'— Геленко, — рішуче сказала бабуся, — йди до своєї ляльки й дов’язуй їй кофтинку. Петлю я знайшла, іди...',402:'Дівчинка трохи здивувалася, може, навіть зацікавилася, але поцілувала руки бабусі й матері та вийшла зі своїми спицями.',403:'— Пане, — провадила старенька, — якщо говорити щиро, мене непокоїть не стільки... Тобто... я не вірю, що Людвік живий. Хто два роки не пише...',404:'— Мамо, досить!...'}
ls=open(p,encoding='utf-8').read().splitlines();i=-1;o=[]
for l in ls:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 o.append(l)
open(p,'w',encoding='utf-8').write('\n'.join(o));print('filled',len(t))
